def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    bg = max(set(x for row in g for x in row), key=lambda x: sum(r.count(x) for r in g))
    original = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if g[r][c] == 2:
                g[r][c] = bg

    def components(test):
        unseen = {(r, c) for r in range(h) for c in range(w) if test(original[r][c])}
        out = []
        while unseen:
            p = unseen.pop()
            comp = {p}
            stack = [p]
            while stack:
                r, c = stack.pop()
                for q in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                    if q in unseen:
                        unseen.remove(q)
                        comp.add(q)
                        stack.append(q)
            out.append(comp)
        return out

    shapes = components(lambda x: x not in (bg, 2))
    reds = components(lambda x: x == 2)

    def bounds(comp):
        rs = [r for r, c in comp]
        cs = [c for r, c in comp]
        return min(rs), max(rs), min(cs), max(cs)

    for shape in shapes:
        top, bottom, left, right = bounds(shape)
        height, width = bottom-top+1, right-left+1
        if height > width:
            for red in reds:
                rt, rb, rl, rr = bounds(red)
                if top <= rt <= bottom and rl > right:
                    edge = max(c for r, c in shape if rt <= r <= rb)
                    for r in range(rt, rb+1):
                        g[r][edge+1] = 2
                        for c in range(edge+2, rl):
                            g[r][c] = 0
                    break
        else:
            # Enclosed background cells identify the socket of a U-shaped object.
            inside = {(r,c) for r in range(top+1,bottom) for c in range(left+1,right)
                      if original[r][c] == bg}
            socket = set()
            while inside:
                seed = inside.pop()
                part = {seed}
                stack = [seed]
                touches = False
                while stack:
                    r,c = stack.pop()
                    if r in (top+1,bottom-1) and (r == top+1 and original[top][c] == bg):
                        touches = True
                    for q in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                        if q in inside:
                            inside.remove(q)
                            part.add(q)
                            stack.append(q)
                if not touches and len(part) >= len(socket):
                    socket = part
            if not socket:
                continue
            st, sb, sl, sr = bounds(socket)
            center = (sl+sr)/2
            for red in reds:
                rt, rb, rl, rr = bounds(red)
                if rb < top and abs((rl+rr)/2-center) <= 1.5:
                    for r in range(st, sb+1):
